// Block (composition) — a scrollable message history with a text composer.
// ScrollArea/Stack own arrangement; Avatar/Form/TextField/Button own their Component behavior and look.
import type { FormEvent, ReactNode, Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Button } from "../components/Button";
import { Form } from "../components/Form";
import { ScrollArea } from "../components/ScrollArea";
import { Stack } from "../layouts/Stack";
import { TextField } from "../components/TextField";
import "./ChatWindow.css";

export interface ChatWindowProps {
  messages: {
    id: string;
    author: string;
    avatarSrc?: string;
    body: ReactNode;
    timestamp?: string;
    own?: boolean;
  }[];
  onSend?: (text: string) => void;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function ChatWindow({ messages, onSend, className, ref }: ChatWindowProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const text = String(new FormData(event.currentTarget).get("message") ?? "").trim();
    if (text) onSend?.(text);
    event.currentTarget.reset();
  };

  return (
    <Stack
      as="section"
      ref={ref}
      gap="large"
      aria-label="Chat"
      className={className ? `sd-chatwindow ${className}` : "sd-chatwindow"}
    >
      {/* The message region scrolls under the Block's max-height but held nothing tabbable — a chat
          history is text and avatars — so a keyboard user could not enter it to scroll (axe
          scrollable-region-focusable / WCAG 2.1.1). ScrollArea is the scrollport and takes the tab
          stop only while it overflows; the Stack inside stays the message arranger, and the live
          region stays on the box whose contents change. */}
      <ScrollArea className="sd-chatwindow__messages" aria-live="polite">
        <Stack gap="small" className="sd-chatwindow__list">
          {messages.map((message) => (
            <Stack
              key={message.id}
              direction="row"
              gap="small"
              align="start"
              data-own={message.own || undefined}
              className="sd-chatwindow__message"
            >
              <Avatar src={message.avatarSrc} size="small" alt={message.author}>
                {message.author.charAt(0).toUpperCase()}
              </Avatar>
              <Stack
                gap="2x-small"
                data-own={message.own || undefined}
                className="sd-chatwindow__bubble"
              >
                <strong className="sd-type-body-medium-emphasized">{message.author}</strong>
                <div className="sd-type-body-medium">{message.body}</div>
                {message.timestamp && (
                  <span className="sd-type-caption-medium">{message.timestamp}</span>
                )}
              </Stack>
            </Stack>
          ))}
        </Stack>
      </ScrollArea>
      <Form onSubmit={handleSubmit}>
        <Stack direction={{ small: "column", medium: "row" }} gap="small" align={{ medium: "end" }} className="sd-chatwindow__composer-row">
          <TextField
            aria-label="Message"
            name="message"
            placeholder="Write a message…"
            isRequired
            className="sd-chatwindow__composer"
          />
          <Button type="submit">Send</Button>
        </Stack>
      </Form>
    </Stack>
  );
}

.sd-chatwindow {
  width: 100%;
  max-height: 36rem;
}

/* The scrollport (a ScrollArea — it owns `overflow-y`, so this must not restate it). The explicit
   `min-height` is also what lets it shrink at all: a flex item defaults to `min-height: auto`, which
   would grow it back to its content instead of scrolling. So this is the floor AND the escape from
   that default — do not add a `min-block-size` beside it, that is the same property and would win.
   Its inline padding is ScrollArea's compensated gutter on both sides, so the messages stay on the
   composer's line; a one-sided override here shifted them by the gutter. */
.sd-chatwindow__messages {
  min-height: 12rem;
}

.sd-chatwindow__message {
  width: 100%;
}

.sd-chatwindow__message[data-own] {
  justify-content: flex-end;
}

.sd-chatwindow__bubble {
  max-width: min(32rem, 75%);
  overflow-wrap: anywhere;
}

.sd-chatwindow__bubble[data-own] {
  align-items: flex-end;
}

.sd-chatwindow__composer {
  width: 100%;
}
